alter table pipeline.layer2_run_items add column if not exists retry_count integer not null default 0 check (retry_count>=0), add column if not exists last_attempt_at timestamptz;
create or replace function public.layer2_run_item_mark(p_item_id uuid,p_status text,p_job_id uuid default null,p_evidence_count integer default null,p_vendor_units numeric default null,p_vendor_cost_usd numeric default null,p_fields_targeted integer default null,p_fields_resolved integer default null,p_blocker text default null) returns boolean language plpgsql security definer set search_path=pg_catalog,pipeline as $$ begin if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; if p_status not in ('queued','discovering','acquiring','extracting','resolved_l2','layer3_required','blocked','cancelled') then raise exception 'invalid item status'; end if; update pipeline.layer2_run_items set status=p_status,job_id=coalesce(p_job_id,job_id),evidence_count=coalesce(p_evidence_count,evidence_count),vendor_units=coalesce(p_vendor_units,vendor_units),vendor_cost_usd=coalesce(p_vendor_cost_usd,vendor_cost_usd),fields_targeted=coalesce(p_fields_targeted,fields_targeted),fields_resolved=coalesce(p_fields_resolved,fields_resolved),blocker=p_blocker,started_at=case when p_status in ('acquiring','extracting') then coalesce(started_at,now()) else started_at end,last_attempt_at=case when p_status='acquiring' then now() else last_attempt_at end,retry_count=case when p_status='acquiring' then retry_count+1 else retry_count end,completed_at=case when p_status in ('resolved_l2','layer3_required','blocked','cancelled') then now() else null end where id=p_item_id; return found; end $$;
create or replace function public.layer2_run_batch_resume(p_batch_id uuid,p_max_attempts integer default 2) returns jsonb language plpgsql security definer set search_path=pg_catalog,pipeline as $$ declare v_n integer; begin if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; if p_max_attempts<1 or p_max_attempts>5 then raise exception 'max attempts out of range'; end if; update pipeline.layer2_run_items set status='queued',blocker=null,completed_at=null where batch_id=p_batch_id and status='blocked' and retry_count<p_max_attempts and blocker ~* '(providers_exhausted|connection|timeout|fetch|network|temporar)'; get diagnostics v_n=row_count; if v_n>0 then update pipeline.layer2_run_batches set status='queued',completed_at=null where id=p_batch_id; end if; return jsonb_build_object('batch_id',p_batch_id,'requeued',v_n,'max_attempts',p_max_attempts); end $$;
revoke all on function public.layer2_run_batch_resume(uuid,integer) from public,anon,authenticated; grant execute on function public.layer2_run_batch_resume(uuid,integer) to service_role;
